\title{The Helly Number of Semicubes, and the Opposite-Semicube\\
Property in Cartesian Products of Partial Cubes}
\author{Aristotle}
\date{July 7, 2026}

\begin{document}
\maketitle

\begin{abstract}
We study the intersection combinatorics of \emph{semicubes} --- the coordinate
halfspaces of a finite hypercube --- and establish that their \textbf{Helly number is
exactly two}: any finite family of semicubes that is pairwise intersecting has a common
vertex. The proof is constructive and yields the common vertex explicitly. The mechanism
is that the only obstruction to a common intersection is a single coordinate demanded in
both of its opposite values; semicubes attached to distinct coordinates never conflict.
This coordinatewise independence has an immediate structural payoff: because a hypercube
is a Cartesian product of lower-dimensional cubes, and cross-coordinate pairs impose no
constraint, the semicube Helly property of a product reduces trivially to that of its
factors. We then examine the refinement in which families are \emph{closed under passing
to opposite semicubes} and explain, at the level of a precise conjecture, why this
refinement first forces the factors of a product to cooperate: a product of two partial
cubes satisfies the opposite-semicube Helly property if and only if both factors are
\emph{harmonic-even}. We situate these results within the theory of partial cubes and
$\Theta$-classes, give algorithms, and pose a program of open problems.
\end{abstract}

\noindent\textbf{Keywords.} hypercube; semicube; halfspace; Helly number; partial cube;
$\Theta$-class; Cartesian product; harmonic-even; local-to-global; constraint
satisfaction.

\section{Introduction}

\subsection{Helly numbers}
A classical theme in combinatorial geometry is the passage from \emph{local} to
\emph{global} intersection. Helly's theorem asserts that if a finite family of convex sets
in $\mathbb{R}^d$ has the property that every $d+1$ of its members have a common point,
then the whole family has a common point. The integer $d+1$ is the \textbf{Helly number}
of the family. For a family $\mathcal{F}$ of sets we say $\mathcal{F}$ has \textbf{Helly
number $k$} if: whenever every subfamily of size at most $k$ has a common element, the
entire family has a common element. Small Helly numbers are desirable computationally,
reducing a global consistency question to the inspection of small subfamilies.

\subsection{The cube and its halfspaces}
Let $\iset$ be a finite coordinate set with $|\iset| = n$. The \textbf{hypercube}
$\HC(\iset)$ has as vertices all binary strings indexed by $\iset$. We use the subset
encoding: a vertex is a subset $s \subseteq \iset$, where $i \in s$ means coordinate $i$
is true and $i \notin s$ means it is false. Two vertices are adjacent when they differ in
one coordinate; the shortest-path distance is the Hamming distance
$d(s,t) = |s \,\triangle\, t|$.

\begin{definition}[Semicube]
For a coordinate $i \in \iset$ and a bit $b \in \{\Htrue, \Hfalse\}$, the
\textbf{semicube} $H(i,b)$ is
\[
  H(i,b) = \{\, s \subseteq \iset : [\,i \in s\,] = b \,\},
\]
where $[\,i \in s\,]$ is the truth value of $i \in s$. Thus $H(i,\Htrue)$ is the set of
vertices containing $i$, and $H(i,\Hfalse)$ the set not containing $i$; each has
$2^{\,n-1}$ vertices.
\end{definition}

The two semicubes of a fixed coordinate are opposite faces of the cube and partition the
vertex set.

\subsection{Results}

\begin{theorem}[Helly number two for semicubes]\label{thm:A}
Let $F$ be a finite family of semicubes of $\HC(\iset)$. If every two members of $F$ have
a common vertex, then all members of $F$ have a common vertex. Equivalently, the
semicubes of a finite hypercube have Helly number $2$.
\end{theorem}

\begin{lemma}[Opposite semicubes are disjoint]\label{lem:disj}
For each coordinate $i$, $H(i,\Htrue) \cap H(i,\Hfalse) = \varnothing$.
\end{lemma}

\begin{lemma}[Coordinatewise determinacy]\label{lem:det}
Let $F$ be a pairwise-intersecting family of semicubes. If $F$ contains both $H(i,b)$ and
$H(i,b')$ for the same coordinate $i$, then $b = b'$.
\end{lemma}

Theorem~\ref{thm:A} is sharp: the Helly number is $2$ \emph{independently of the
dimension} $n$. The structural reason is coordinatewise independence --- semicubes of
different coordinates always intersect --- which yields the product reduction below.

\begin{corollary}[Product reduction]\label{cor:B}
The semicube Helly property of a Cartesian product of hypercubes holds because it holds in
each factor: cross-factor pairs impose no constraint, so the product's Helly number equals
the maximum of the factors' Helly numbers, namely $2$.
\end{corollary}

\begin{conjecture}[Opposite-semicube characterization]\label{conj:C}
A Cartesian product of two partial cubes satisfies the \emph{opposite-semicube Helly
property} --- every pairwise-intersecting family closed under opposites has a common
vertex --- if and only if both factors are \textbf{harmonic-even}.
\end{conjecture}

\section{Preliminaries}
Vertices of $\HC(\iset)$ are subsets $s \subseteq \iset$. We identify a semicube with the
pair $(i,b) \in \iset \times \{\Htrue,\Hfalse\}$ naming it; a \textbf{family} is a finite
set $F$ of such pairs. $F$ is \textbf{pairwise intersecting} if for all distinct
$(i,b),(j,c) \in F$ the set $H(i,b) \cap H(j,c)$ is nonempty. A vertex $v$ is
\textbf{common} to $F$ if $v \in H(i,b)$ for all $(i,b) \in F$.

A connected graph $G$ is a \textbf{partial cube} if it embeds isometrically into a
hypercube. The Djokovi\'c--Winkler relation $\Theta$ groups edges into classes; each
$\Theta$-class, when removed, splits $G$ into two convex halves, its opposite
\textbf{semicubes}. In the cube, the $\Theta$-class of coordinate $i$ is the set of edges
flipping $i$, with halves $H(i,\Htrue)$ and $H(i,\Hfalse)$. A partial cube is
\textbf{harmonic-even} if every $\Theta$-class splits the vertex set into two equal parts
and this balance is inherited by every convex subgraph.

\section{The Helly number of semicubes}

\begin{proof}[Proof of Lemma~\ref{lem:disj}]
A vertex $s$ lies in $H(i,\Htrue)$ iff $i \in s$ and in $H(i,\Hfalse)$ iff $i \notin s$.
No $s$ satisfies both, so the intersection is empty.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:det}]
Suppose $b \neq b'$; for bits this forces $\{b,b'\} = \{\Htrue,\Hfalse\}$. Then $(i,b)$
and $(i,b')$ are distinct members of $F$, so $H(i,b) \cap H(i,b')$ is nonempty by pairwise
intersection. But that set equals $H(i,\Htrue) \cap H(i,\Hfalse) = \varnothing$ by
Lemma~\ref{lem:disj}, a contradiction. Hence $b=b'$.
\end{proof}

Lemma~\ref{lem:det} says a pairwise-intersecting family induces a well-defined partial
assignment $\alpha(i) = b$ whenever $(i,b) \in F$.

\begin{proof}[Proof of Theorem~\ref{thm:A}]
By Lemma~\ref{lem:det} the family determines a well-defined partial assignment. Define
\[
  v = \{\, i \in \iset : (i,\Htrue) \in F \,\}.
\]
Take any $(i,b) \in F$. If $b = \Htrue$, then $i \in v$ by definition, so
$v \in H(i,\Htrue) = H(i,b)$. If $b = \Hfalse$, suppose for contradiction $i \in v$; then
$(i,\Htrue) \in F$, while also $(i,\Hfalse) \in F$, contradicting
Lemma~\ref{lem:det}. Hence $i \notin v$ and $v \in H(i,\Hfalse) = H(i,b)$. In both cases
$v$ lies in the chosen semicube; as $(i,b)$ was arbitrary, $v$ is common to $F$. A family
with a global intersection is a fortiori pairwise intersecting, so the two conditions are
equivalent. The number is exactly $2$, not $1$, since two opposite semicubes are
individually nonempty yet disjoint.
\end{proof}

\begin{remark}
The witness $v$ is canonical: it turns on precisely the coordinates the family demands to
be true. No search is required, which is why the Helly number does not grow with $n$.
\end{remark}

\section{Independence, products, and the isometric host}

\begin{proposition}[Cross-coordinate pairs never obstruct]\label{prop:cross}
If $i \neq j$, then for all bits $b,c$ the semicubes $H(i,b)$ and $H(j,c)$ intersect.
\end{proposition}

\begin{proof}
Choose a vertex $s$ with $[\,i\in s\,]=b$ and $[\,j\in s\,]=c$; remaining coordinates are
free. Such $s$ exists since $i \neq j$, and lies in both semicubes.
\end{proof}

Combining Lemma~\ref{lem:disj} and Proposition~\ref{prop:cross}: \emph{two semicubes fail
to intersect if and only if they are the two opposite halves of a single coordinate.}

\begin{proof}[Proof of Corollary~\ref{cor:B}]
Write $\iset = \iset_1 \sqcup \iset_2$, so $\HC(\iset) \cong \HC(\iset_1) \times
\HC(\iset_2)$. Partition $F$ into $F_1$ (coordinate in $\iset_1$) and $F_2$ (coordinate in
$\iset_2$). Each $F_k$ is pairwise intersecting in its factor, hence has a common vertex
$v_k$ by Theorem~\ref{thm:A}. By Proposition~\ref{prop:cross} no cross pair obstructs, so
$(v_1,v_2)$ is common to $F$.
\end{proof}

Because the hypercube is an isometric host, the semicubes $H(i,b)$ are genuine
$\Theta$-classes, and every statement above transfers to any partial cube by reading
``$H(i,b)$'' as the two convex halves of the $i$-th $\Theta$-class.

\section{The opposite-closed refinement}

The plain property is insensitive to the factors (Corollary~\ref{cor:B}). To detect
cooperation we strengthen the closure condition.

\begin{definition}[Opposite-semicube Helly property]
A partial cube $G$ satisfies the \textbf{opposite-semicube Helly property} if every
pairwise-intersecting family of $\Theta$-class halves that is closed under the involution
$(i,b)\mapsto(i,\bar b)$ has a common vertex.
\end{definition}

For the plain property, the sole obstruction is an opposite pair
(Lemma~\ref{lem:disj}, Proposition~\ref{prop:cross}). Under opposite closure an opposite
pair is always formally present, so it can no longer be decisive; what replaces it is a
\textbf{parity/balance} condition. A coordinate can be reconciled only when its two
opposite halves are interchangeable across convex subgraphs --- exactly
harmonic-evenness. This motivates Conjecture~\ref{conj:C}.

\begin{proof}[Heuristic justification of Conjecture~\ref{conj:C}]
By Corollary~\ref{cor:B} cross-factor pairs never obstruct, so the property decouples into
a condition per factor. Within a factor, reconciling opposite-closed
pairwise-intersecting families amounts to balancing the two halves of each
$\Theta$-class uniformly over convex subgraphs, i.e. harmonic-evenness. Necessity: a
non-harmonic-even factor has an unbalanced $\Theta$-class whose halves cannot be
reconciled. Sufficiency: balance extends a factorwise common vertex across the closure.
The plain cube is degenerate: each class splits $2^n$ vertices into two equal halves,
harmonic-evenness is automatic, and the Helly number collapses to $2$.
\end{proof}

\begin{conjecture}[Helly number equals isometric dimension]\label{conj:D}
For a partial cube $G$, the Helly number of its family of $\Theta$-class halves equals the
number of \emph{independent} $\Theta$-classes of $G$ (not their raw count). The full cube
carries $n$ classes yet has Helly number $2$, so the raw count is the wrong invariant.
\end{conjecture}

\begin{conjecture}[Products create harmonic-evenness]\label{conj:E}
The Cartesian product of two harmonic-even partial cubes is harmonic-even, and every
harmonic-even partial cube that is not a single vertex factors as a nontrivial product of
harmonic-even partial cubes.
\end{conjecture}

\section{Algorithms}

\paragraph{Consistency by coordinate folding.} Given $F$ as a list of pairs $(i,b)$, $F$
is pairwise intersecting iff no coordinate carries two bits
(Lemma~\ref{lem:det},~Proposition~\ref{prop:cross}).
\begin{enumerate}
\item Initialize an empty map $\alpha$ from coordinates to bits.
\item For each $(i,b) \in F$: if $i \notin \alpha$, set $\alpha(i)=b$; else if
$\alpha(i)\neq b$, report \emph{inconsistent} and stop.
\item Otherwise report \emph{consistent} with witness $v = \{\, i : \alpha(i)=\Htrue \,\}$.
\end{enumerate}
Correctness is Theorem~\ref{thm:A}. Running time $O(|F|)$ with hashing and $O(|\iset|)$
space; no vertex enumeration. For a product, split $F$ by factor and run in parallel
(Corollary~\ref{cor:B}).

\section{Applications}
A conjunction of unit constraints ``coordinate $i$ equals $b$'' is satisfiable iff
pairwise satisfiable; Theorem~\ref{thm:A} is the geometric reason $2$-consistency
suffices, and folding is unit propagation seen as a Helly phenomenon. Semicubes are the
halfspaces of median spaces and CAT(0) cube complexes, where the ``no two opposite
halfspaces'' condition underlies Helly-type structure theorems. In distributed agreement,
independent agents constraining single coordinates reach consensus exactly when no
coordinate is contested.

\section{Discussion and open problems}
We proved Helly number $2$ for hypercube semicubes with a canonical witness, identified
opposite pairs as the unique obstruction, and showed the plain property factors trivially
across products. The opposite-closed refinement is where products become nontrivial
(Conjecture~\ref{conj:C}). Open problems: prove Conjecture~\ref{conj:C} (obstruction and
balancing extension); formalize ``independent $\Theta$-classes'' for
Conjecture~\ref{conj:D}; establish Conjecture~\ref{conj:E}; and seek fractional/colorful
Helly variants with dimension-free constants matching the exact Helly number $2$.

\appendix
\section{Worked micro-examples}
\begin{itemize}
\item \textbf{Single coordinate.} $F=\{(i,\Htrue),(i,\Hfalse)\}$ is not pairwise
intersecting (Lemma~\ref{lem:disj}); it has no common vertex, showing the Helly number is
not $1$.
\item \textbf{Three coordinates.} In $\HC$ on $\{1,2,3\}$, $F=\{(1,\Htrue),(2,\Hfalse),
(3,\Htrue)\}$ is pairwise intersecting; witness $v=\{1,3\}$ (string $101$).
\item \textbf{Product.} In $\HC_2\times\HC_2$ with left coordinates $\{1,2\}$ and right
$\{3,4\}$, $F=\{(1,\Htrue),(3,\Hfalse)\}$ splits and the cross pair never obstructs
(Proposition~\ref{prop:cross}).
\end{itemize}

