"""Canonical-witness construction for a family of semicubes (Theorem A)."""
from __future__ import annotations
from typing import Dict, FrozenSet, Iterable, Optional, Tuple

Semicube = Tuple[int, bool]
Vertex = FrozenSet[int]


def semicube_common_vertex(family: Iterable[Semicube]) -> Optional[Vertex]:
    """Return the canonical common vertex v = {i : (i, True) in family},
    or None if some coordinate is demanded in both directions."""
    assignment: Dict[int, bool] = {}
    for i, b in family:
        if i in assignment and assignment[i] != b:
            return None            # opposite pair: the unique obstruction
        assignment[i] = b
    return frozenset(i for i, b in assignment.items() if b)


if __name__ == "__main__":
    fam = [(0, True), (1, False), (3, True)]
    v = semicube_common_vertex(fam)
    print("family :", fam)
    print("witness:", sorted(v) if v is not None else None)
    print("valid  :", v is not None and all((i in v) == b for i, b in fam))

"""Exhaustive verification of Helly number 2 on the cube Q(n)."""
from __future__ import annotations
from itertools import combinations, product
from typing import FrozenSet, List, Optional, Tuple

Semicube = Tuple[int, bool]
Vertex = FrozenSet[int]


def all_vertices(n: int) -> List[Vertex]:
    return [frozenset(i for i, b in enumerate(bits) if b)
            for bits in product((False, True), repeat=n)]


def witness(family: List[Semicube]) -> Optional[Vertex]:
    a = {}
    for i, b in family:
        if i in a and a[i] != b:
            return None
        a[i] = b
    return frozenset(i for i, b in a.items() if b)


def pairwise(n: int, fam: List[Semicube]) -> bool:
    V = all_vertices(n)
    for (i, b), (j, c) in combinations(fam, 2):
        if not any((i in v) == b and (j in v) == c for v in V):
            return False
    return True


def globally(n: int, fam: List[Semicube]) -> bool:
    return any(all((i in v) == b for i, b in fam) for v in all_vertices(n))


def verify(n: int, kmax: int) -> int:
    scs = [(i, b) for i in range(n) for b in (True, False)]
    count = 0
    for k in range(1, kmax + 1):
        for fam in combinations(scs, k):
            fam = list(fam)
            assert pairwise(n, fam) == globally(n, fam) == (witness(fam) is not None)
            count += 1
    return count


if __name__ == "__main__":
    print("families verified on Q(4):", verify(4, 3))

"""Factorwise solution of a semicube family in a Cartesian product (Corollary B)."""
from __future__ import annotations
from typing import Dict, FrozenSet, List, Optional, Tuple

Semicube = Tuple[int, bool]
Vertex = FrozenSet[int]


def solve(fam: List[Semicube]) -> Optional[Vertex]:
    a: Dict[int, bool] = {}
    for i, b in fam:
        if i in a and a[i] != b:
            return None
        a[i] = b
    return frozenset(i for i, b in a.items() if b)


def product_solve(left_dim: int, right_dim: int,
                  fam: List[Semicube]) -> Optional[Vertex]:
    """Split by factor, solve independently, recombine (cross pairs never obstruct)."""
    left = [(i, b) for i, b in fam if i < left_dim]
    right = [(i, b) for i, b in fam if i >= left_dim]
    vl, vr = solve(left), solve(right)
    if (left and vl is None) or (right and vr is None):
        return None
    return frozenset(set(vl or set()) | set(vr or set()))


if __name__ == "__main__":
    fam = [(0, True), (3, False)]         # coord 0 left, coord 3 right in Q(2)xQ(2)
    v = product_solve(2, 2, fam)
    print("combined witness:", sorted(v) if v is not None else None)
    print("valid           :", v is not None and all((i in v) == b for i, b in fam))

